{mode === 'edit' && tool && (
  <ToolForm
    defaultValues={tool}
    onSubmit={values => updateTool.mutate({ id: tool.id, data: values })}
    isLoading={updateTool.isPending}
    onCancel={onClose}
  />
)}

{(['view', 'edit', 'delete'] as const).map((action) => (
  <button
    key={action}
    onClick={() => {
      onAction(action, tool)
      setMenuOpen(false)
    }}
    className={`w-full text-left px-4 py-2 text-sm hover:bg-gray-100 dark:hover:bg-gray-700 capitalize ${action === 'delete' ? 'text-red-500 border-t border-red-200' : ''}`}
  >
    {action === 'view' ? 'View' : action === 'edit' ? 'Edit' : 'Delete'}
  </button>
))}

export const useUpdateTool = (onSuccess?: () => void) => {
  const qc = useQueryClient()
  return useMutation({
    mutationFn: ({ id, data }: { id: number; data: Partial<Tool> }) => toolMutations.update(id, data),
    onSuccess: () => { qc.invalidateQueries({ queryKey: ['tools'] }); onSuccess?.() },
  })
}

{mode === 'delete' && tool && (
  <div className="flex flex-col gap-4">
    <p className="text-sm text-gray-500">Supprimer <strong>{tool.name}</strong> ? Cette action est irréversible.</p>
    <div className="flex gap-2 justify-end">
      <button onClick={onClose} className="px-4 py-2 rounded-lg border text-sm hover:bg-gray-50 dark:hover:bg-gray-700">Annuler</button>
      <button
        onClick={() => deleteTool.mutate(tool.id)}
        disabled={deleteTool.isPending}
        className="px-4 py-2 rounded-lg bg-red-500 text-white text-sm hover:bg-red-600 disabled:opacity-50"
      >
        {deleteTool.isPending ? 'Suppression...' : 'Supprimer'}
      </button>
    </div>
  </div>
)}

const form = useForm({
  defaultValues: {...},
  validatorAdapter: standardSchemaValidators,
  validators: { onChange: toolSchema },
  onSubmit: ({ value }) => onSubmit(value),
})

const Field = ({ label, error, children }: { label: string; error?: string; children: React.ReactNode }) => (
  <div className="flex flex-col gap-1">
    <label className="text-xs font-medium text-gray-500">{label}</label>
    {children}
    {error && <p className="text-xs text-red-500">{error}</p>}
  </div>
)

export const useCreateTool = (onSuccess?: () => void) => {
  const qc = useQueryClient()
  return useMutation({
    mutationFn: (data: Partial<Tool>) => toolMutations.create(data),
    onSuccess: () => { qc.invalidateQueries({ queryKey: ['tools'] }); onSuccess?.() },
  })
}

const createTool = useCreateTool(onClose)
const updateTool = useUpdateTool(onClose)
const deleteTool = useDeleteTool(onClose)
